<?php

namespace App\Actions\Finance;

use App\Models\FinancialEntry;
use Illuminate\Validation\ValidationException;

/**
 * Soft delete a manual entry (US-10.1). Entries generated by payments are
 * kept, even for the admin: they are cancelled by the payment refund.
 */
class DeleteFinancialEntry
{
    /**
     * @throws ValidationException
     */
    public function handle(FinancialEntry $entry): void
    {
        if ($entry->isAutomatic()) {
            throw ValidationException::withMessages(['entry' => 'Lançamento automático de mensalidade não pode ser excluído; use o estorno do pagamento.']);
        }

        $entry->delete();
    }
}
